from __future__ import annotations
import json
from pathlib import Path
from typing import Any
ROOT=Path(__file__).resolve().parents[2]
RESULT=ROOT/'evaluation-data/results/task0280-formal-modern-control-center-video-recording'
RECORDING=ROOT/'evaluation-data/showcase/recording/task0280'
PREV=ROOT/'evaluation-data/results/task0279-ui-polish-recording-freeze-and-final-acceptance'
TASK=ROOT/'tasks/TASK-0280_formal_modern_control_center_video_recording.md'
REPORT=ROOT/'docs/TASK0280_FORMAL_MODERN_CONTROL_CENTER_VIDEO_RECORDING.md'
def read(p:Path)->dict[str,Any]: return json.loads(p.read_text(encoding='utf-8'))
def write(name:str,payload:dict[str,Any]): RESULT.mkdir(parents=True,exist_ok=True);(RESULT/name).write_text(json.dumps(payload,ensure_ascii=False,indent=2,sort_keys=True)+'\n',encoding='utf-8')
def entry()->dict[str,Any]:
 s=read(PREV/'summary.json');v=read(PREV/'verification.json');g={'task0279_complete':s.get('task_status')=='complete','task0279_verified':v.get('verification_passed') is True,'ui_stage_complete':s.get('candidate_decision')=='modern_control_center_ui_stage_complete','recording_ready':s.get('modern_control_center_recording_ready') is True,'zero_ui_blockers':s.get('known_ui_blocker_count')==0,'zero_recording_blockers':s.get('known_recording_blocker_count')==0,'runtime_trace_unchanged':s.get('runtime_trace_authority_changed') is False,'rag_unchanged':s.get('rag_backend_architecture_changed') is False,'agent_unchanged':s.get('production_agent_authority_changed') is False};return {'schema_version':'opk-rag.task0280.entry-authority.v1','gates':g,'entry_gate_passed':all(g.values())}
def contracts()->dict[str,dict[str,Any]]:
 return {
 'controller_contract.json':{'modern_control_center':True,'scene_order':['intro','s01','s02','s03','s03_graph','s03_lineage','s04','close'],'scenario_order':['S01','S02','S03','S04'],'controller_executes_scenario':False,'trace_source':'committed TASK-0279 executed rehearsal snapshots','recording_mode':True},
 'recording_policy.json':{'clean_committed_worktree_required':True,'screen_first_voiceover_later':True,'selected_master_audio_allowed':False,'retry_to_preferred_answer_allowed':False,'infrastructure_retry_allowed':True,'semantic_retry_allowed':False},
 's04_variance_policy.json':{'formal_take_uses_live_task0279_s04':True,'live_s04_answerability':False,'live_s04_refusal_reason':'no_relevant_context','live_s04_failure_stage':None,'canonical_later_abstention_preserved_separately':True,'live_equals_canonical':False,'rerun_to_obtain_canonical_variant':False,'refused_equals_failed':False},
 'runtime_integrity.json':{'ui_decision_authority':False,'graph_max_hop':1,'recovery_max_attempts':1,'runtime_trace_authority_changed':False,'retrieval_behavior_changed':False,'agent_behavior_changed':False,'graph_behavior_changed':False,'rerank_behavior_changed':False,'evidence_behavior_changed':False,'answerability_behavior_changed':False,'generation_behavior_changed':False,'grounding_behavior_changed':False,'citation_behavior_changed':False,'new_llm_invocation_added':False},
 'authority_boundary.json':{'recording_layer_runtime_authority':False,'ui_decision_authority':False,'graph_max_hop':1,'recovery_max_attempts':1,'runtime_trace_authority_changed':False,'rag_backend_architecture_changed':False,'production_agent_authority_changed':False},
 }
def run()->dict[str,Any]:
 e=entry();write('entry_authority.json',e)
 for n,p in contracts().items():write(n,p)
 required=['recording_preflight.json','recording_environment.json','recording_attempts.json','formal_take_manifest.json','video_integrity.json','representative_frame_validation.json','privacy_scan.json','public_claim_audit.json','trace_alignment.json','frontend_validation.json','backend_validation.json']
 missing=[x for x in required if not (RESULT/x).is_file()]; ext={x:read(RESULT/x) for x in required if (RESULT/x).is_file()}
 gates={'entry':e['entry_gate_passed'],'clean_committed_baseline':ext.get('recording_preflight.json',{}).get('clean_committed_worktree') is True,'formal_take':ext.get('formal_take_manifest.json',{}).get('selected') is True,'video_integrity':ext.get('video_integrity.json',{}).get('video_integrity_passed') is True,'representative_frames':ext.get('representative_frame_validation.json',{}).get('validation_passed') is True,'trace_alignment':ext.get('trace_alignment.json',{}).get('trace_alignment_passed') is True,'privacy':ext.get('privacy_scan.json',{}).get('scan_passed') is True,'public_claims':ext.get('public_claim_audit.json',{}).get('unsupported_claim_count')==0,'frontend':ext.get('frontend_validation.json',{}).get('regression_passed') is True,'backend':ext.get('backend_validation.json',{}).get('governed_regressions_passed') is True and ext.get('backend_validation.json',{}).get('focused_tests_passed') is True,'runtime_integrity':contracts()['runtime_integrity.json']['new_llm_invocation_added'] is False and not any(v for k,v in contracts()['runtime_integrity.json'].items() if k.endswith('_behavior_changed') or k.endswith('_authority_changed'))}
 complete=not missing and all(gates.values())
 summary={'schema_version':'opk-rag.task0280.summary.v1','task_id':'TASK-0280','task_status':'complete' if complete else 'partial','candidate_decision':'formal_modern_control_center_video_recorded' if complete else 'hold_for_recording_validation','next_decision':'advance_to_modern_video_editing_packaging_and_final_delivery' if complete else None,'formal_video_recorded':complete,'selected_take':ext.get('formal_take_manifest.json',{}).get('selected_take'),'git_recording_baseline':ext.get('formal_take_manifest.json',{}).get('git_head'),'known_recording_blocker_count':0 if complete else len(missing),'retry_to_preferred_answer':False,'runtime_trace_authority_changed':False,'rag_backend_architecture_changed':False,'production_agent_authority_changed':False,'graph_max_hop':1,'recovery_max_attempts':1,'gates':gates,'missing_artifacts':missing};write('summary.json',summary);return summary
def verify()->dict[str,Any]:
 needed=['entry_authority.json','controller_contract.json','recording_policy.json','recording_preflight.json','recording_environment.json','recording_attempts.json','formal_take_manifest.json','video_integrity.json','representative_frame_validation.json','privacy_scan.json','public_claim_audit.json','trace_alignment.json','s04_variance_policy.json','runtime_integrity.json','frontend_validation.json','backend_validation.json','authority_boundary.json','summary.json'];missing=[x for x in needed if not (RESULT/x).is_file()];s=read(RESULT/'summary.json') if (RESULT/'summary.json').is_file() else {};checks={'required_artifacts':not missing,'task':TASK.is_file(),'report':REPORT.is_file(),'formal_video_recorded':s.get('formal_video_recorded') is True,'preferred':s.get('candidate_decision')=='formal_modern_control_center_video_recorded','next_decision':s.get('next_decision')=='advance_to_modern_video_editing_packaging_and_final_delivery','zero_blockers':s.get('known_recording_blocker_count')==0,'retry_to_preferred_answer_false':s.get('retry_to_preferred_answer') is False,'runtime_trace_unchanged':s.get('runtime_trace_authority_changed') is False,'rag_unchanged':s.get('rag_backend_architecture_changed') is False,'agent_unchanged':s.get('production_agent_authority_changed') is False};return {'schema_version':'opk-rag.task0280.verification.v1','task_id':'TASK-0280','verification_passed':all(checks.values()),'checks':checks,'missing_artifacts':missing,'candidate_decision':s.get('candidate_decision')}
